mapper.update:
UPDATE tc_work_carrier_slot
   SET slot_state = #{s.slotState},
       lot_id     = #{s.lotId},
       updated_at = CURRENT_TIMESTAMP
 WHERE work_carrier_key = #{s.workCarrierKey}
   AND slot_no = #{s.slotNo}

mapper.select:
SELECT 
  FROM tc_work_carrier_slot
 WHERE work_carrier_key = #{workCarrierKey}
   AND slot_no = #{slotNo}

SELECT 
  FROM tc_work_carrier_slot
 WHERE work_carrier_key = #{workCarrierKey}
 ORDER BY slot_no ASC
 LIMIT #{limit} OFFSET #{offset}

mapper.delete:
DELETE FROM tc_work_carrier_slot
 WHERE work_carrier_key = #{workCarrierKey}
   AND slot_no = #{slotNo}
